func (sh *strictHandler) RelinkWatch(ctx *echo.Context, id IDParam) error {
	var request RelinkWatchRequestObject

	request.Id = id

	var body RelinkWatchJSONRequestBody
	var err error
	if _, ok := ctx.Echo().Binder.(*echo.DefaultBinder); ok {
		// Bind only the request body, so that path and query parameters
		// are not also bound into the body struct.
		err = echo.BindBody(ctx, &body)
	} else {
		// A custom binder is installed on the Echo instance; defer to it
		// entirely, since echo.Binder does not expose body-only binding.
		err = ctx.Bind(&body)
	}
	if err != nil {
		return err
	}
	request.Body = &body

	handler := func(ctx *echo.Context, request interface{}) (interface{}, error) {
		return sh.ssi.RelinkWatch(ctx.Request().Context(), request.(RelinkWatchRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "RelinkWatch")
	}

	response, err := handler(ctx, request)

	if err != nil {
		return err
	} else if validResponse, ok := response.(RelinkWatchResponseObject); ok {
		return validResponse.VisitRelinkWatchResponse(ctx.Response())
	} else if response != nil {
		return fmt.Errorf("unexpected response type: %T", response)
	}
	return nil
}

